import { expect, expectStatus, test } from "../../fixtures";

test("an admin approves a vendor's w9 extraction and the vendor stays in the review queue", { tag: "@LIF-12" }, async ({ apiAs, factory }) => {
  // Arrange
  const { vendor, documents, extractions } = await factory.vendorInReview();
  const admin = await apiAs("admin");

  // Act
  const decision = await admin.post(`/api/extractions/${extractions.w9.id}/decision`, {
    data: { decision: "approve" },
  });
  const queue = await admin.get("/api/review-queue");

  // Assert
  const approved = await expectStatus<{ id: string; status: string }>(decision, 200);
  expect(approved.id).toBe(extractions.w9.id);
  expect(approved.status).toBe("approved");
  const items = await expectStatus<{ vendor_id: string; vendor_name: string }[]>(queue, 200);
  expect(items.map((item) => item.vendor_id)).toContain(vendor.id);
  // Stored outcome, not just the echoed response
  expect((await factory.extraction(documents.w9.id, "admin")).status).toBe("approved");
});
